import assert from 'node:assert/strict';
import test from 'node:test';
import * as imported from 'file:///D:/xiangmu/NBshiyan-m1-t2/src/lib/contracts/index.ts';
const contracts = imported.default ?? imported;

const time = '2026-10-20T12:00:00.000Z';
const conversation = {
  id: 'conversation-1', locale: 'en', productSlug: null, sourcePath: null,
  status: 'OPEN', version: 0, createdAt: time, updatedAt: time,
  lastActivityAt: time, retainUntil: '2026-11-20T12:00:00.000Z', anonymizedAt: null,
};
const message = seq => ({ id: `message-${seq}`, seq, sender: 'VISITOR', bodyText: 'Hello', createdAt: time });
const sync = (seqs, nextAfterSeq = 5) => ({ conversation, messages: seqs.map(message), lastSeq: 5, nextAfterSeq, hasMore: false, read: { lastReadSeq: 0 } });

test('R1: public and admin chat schemas reject incomplete ranges and cursor jumps', () => {
  const results = [];
  for (const schema of [contracts.ChatSyncDTOSchema, contracts.AdminChatSyncDTOSchema]) {
    const admin = schema === contracts.AdminChatSyncDTOSchema;
    for (const seqs of [[3, 5], [3]]) {
      const value = sync(seqs);
      if (admin) value.conversation = { ...conversation, email: null };
      const result = schema.safeParse(value);
      console.log(JSON.stringify({ case: 'R1', admin, seqs, nextAfterSeq: 5, accepted: result.success }));
      results.push(result.success);
    }
  }
  assert.deepEqual(results, [false, false, false, false], 'Incomplete returned messages must not advance the cursor beyond the complete range.');
});

test('R2: optional blank chat email is treated as omitted', () => {
  const value = {
    clientConversationId: '2cba8760-8b82-4f32-9ff0-f1b3c426d490',
    clientMessageId: '3cba8760-8b82-4f32-9ff0-f1b3c426d490',
    locale: 'en', bodyText: 'Hello',
  };
  assert.equal(contracts.ConversationCreateRequestSchema.safeParse(value).success, true);
  const accepted = [];
  for (const email of ['', '   ']) {
    const result = contracts.ConversationCreateRequestSchema.safeParse({ ...value, email });
    console.log(JSON.stringify({ case: 'R2', email, accepted: result.success }));
    accepted.push(result.success);
  }
  assert.deepEqual(accepted, [true, true], 'Blank optional email must behave like omission.');
});
